# 找到 </style> 标签并插入新的 CSS
style_end = content.find('</style>')
if style_end != -1:
    content = content[:style_end] + icon_css + '\n    ' + content[style_end:]

# 替换按钮内容（使用 <span> 包含图标）
old_buttons = '''        <button class="auth-btn" onclick="tencentLogin()" style="background:linear-gradient(135deg,#07c160,#09ad55);flex:1;min-width:120px;">🟢 微信登录</button>
        <button class="auth-btn" onclick="qqLogin()" style="background:linear-gradient(135deg,#12b7f5,#0d9ddf);flex:1;min-width:120px;">💙 QQ登录</button>
        <button class="auth-btn" onclick="githubLogin()" style="background:linear-gradient(135deg,#333,#555);flex:1;min-width:120px;">🐱 GitHub登录</button>'''

new_buttons = '''        <button class="auth-btn" onclick="tencentLogin()" style="background:linear-gradient(135deg,#07c160,#09ad55);flex:1;min-width:120px;"><span class="icon-wechat"></span>微信登录</button>
        <button class="auth-btn" onclick="qqLogin()" style="background:linear-gradient(135deg,#12b7f5,#0d9ddf);flex:1;min-width:120px;"><span class="icon-qq"></span>QQ登录</button>
        <button class="auth-btn" onclick="githubLogin()" style="background:linear-gradient(135deg,#333,#555);flex:1;min-width:120px;"><span class="icon-github"></span>GitHub登录</button>'''

content = content.replace(old_buttons, new_buttons)

# 写回文件
with open('/workspace/index.html', 'w', encoding='utf-8') as f:
    f.write(content)

print("✅ 已使用真实SVG图标替换Emoji")
